                    new DocBullet("Clear any debug tracking before a release — see The ModForge tab."))),

            new DocTopic("Exporting and installing",
                "Getting the pack into the game.",
                new DocSection("",
                    new DocBullet("Export pack (Ctrl+E)", "Saves, then bundles the pack folder into a single .smspack. The first export asks where; after that the same place is reused."),
                    new DocBullet("Export pack as… (Ctrl+Shift+E)", "Always asks, and the place you choose becomes the new one-click target."),
                    new DocBullet("Installing", "Put the .smspack in BepInEx/plugins/SMSModForge/ModPacks/ inside the game folder. Exporting straight there means testing a change is export, then restart the game."),
                    new DocBullet("Game version", "Each save records which version of the game the pack was built against, and the editor shows that version in its title bar. It travels with the pack, so a pack built for one version can be recognised when the game moves on.")),
                new DocSection("Worth knowing",
                    new DocBullet("Export is unavailable until the pack has been saved at least once."),
                    new DocBullet("See Packs and the .smspack for what ends up inside the file.")))),
    };
}
